import { execFile } from "node:child_process";
import { promisify } from "node:util";

const run = promisify(execFile);

export interface UpdateResult {
  updated: boolean;
  /** Why nothing changed, or what changed. */
  reason: string;
  changedFiles: string[];
  /** Harmless local differences that were reset before updating. */
  restoredFiles: string[];
}

/** Regenerated by npm on install; local rewrites are not real edits. */
const REGENERATED = new Set(["package-lock.json"]);

async function git(cwd: string, args: string[]) {
  const { stdout } = await run("git", args, { cwd, windowsHide: true, maxBuffer: 10 * 1024 * 1024 });
  return stdout.trim();
}

/**
 * Fetches `branch` from `remote` and fast-forwards the current checkout to it.
 * Safe by design: never merges, rebases or overwrites. It skips the update when tracked
 * files have local edits, or when the remote history isn't a straight continuation of
 * the local one. Untracked/ignored files such as .env are never touched.
 */
export async function checkForUpdates(cwd: string, remote: string, branch: string): Promise<UpdateResult> {
  const none = { changedFiles: [] as string[], restoredFiles: [] as string[] };
  // Tracked files that differ from the last commit...
  const dirty = (await git(cwd, ["diff", "HEAD", "--name-only"])).split("\n").filter(Boolean);
  // ...and those with real content edits (ignoring Windows line-ending differences).
  // (--numstat honours --ignore-cr-at-eol; --name-only does not.)
  const real = new Set((await git(cwd, ["diff", "HEAD", "--numstat", "--ignore-cr-at-eol"]))
    .split("\n").filter(Boolean).map((line) => line.split("\t").slice(2).join("\t")));
  const blocking = dirty.filter((f) => real.has(f) && !REGENERATED.has(f));
  if (blocking.length) {
    const shown = blocking.slice(0, 5).join(", ") + (blocking.length > 5 ? ` (+${blocking.length - 5} more)` : "");
    return { updated: false, reason: `you edited ${shown}; not updating so your changes are kept`, ...none };
  }

  await git(cwd, ["fetch", "--quiet", remote, branch]);
  const head = await git(cwd, ["rev-parse", "HEAD"]);
  const incoming = await git(cwd, ["rev-parse", "FETCH_HEAD"]);
  if (head === incoming) return { updated: false, reason: "already up to date", ...none };

  try {
    await git(cwd, ["merge-base", "--is-ancestor", head, incoming]);
  } catch {
    return { updated: false, reason: "update is not a straight continuation of your copy; not updating", ...none };
  }

  // Only harmless differences remain (npm-rewritten lockfile, line endings): reset them.
  if (dirty.length) await git(cwd, ["checkout", "HEAD", "--", ...dirty]);
  const changed = (await git(cwd, ["diff", "--name-only", head, incoming])).split("\n").filter(Boolean);
  await git(cwd, ["merge", "--ff-only", "--quiet", incoming]);
  return { updated: true, reason: `updated to ${incoming.slice(0, 7)}`, changedFiles: changed, restoredFiles: dirty };
}
